from pathlib import Path

# Dense packed-region writer --------------------------------------------------
p = Path('src/main/java/dev/comfyfluffy/caustica/rt/terrain/RtCausticaLodRegionStore.java')
s = p.read_text()
start = s.index('    static void writeRegion(Path root, int regionX, int regionZ, Map<Integer, TileData> tiles) throws IOException {')
end = s.index('    static int regionX(int chunkX) {', start)
old = s[start:end]
new = '''    static void writeRegion(Path root, int regionX, int regionZ, Map<Integer, TileData> tiles) throws IOException {\n        if (tiles.isEmpty()) {\n            return;\n        }\n        TileData[] dense = new TileData[REGION_SLOTS];\n        for (Map.Entry<Integer, TileData> entry : tiles.entrySet()) {\n            int index = entry.getKey();\n            if (index < 0 || index >= REGION_SLOTS) {\n                throw new IllegalArgumentException("CausticaLOD region slot out of range: " + index);\n            }\n            dense[index] = entry.getValue();\n        }\n        writeRegion(root, regionX, regionZ, dense);\n    }\n\n    /** Dense no-boxing path used by the WynnLOD bulk publisher. */\n    static void writeRegion(Path root, int regionX, int regionZ, TileData[] tiles) throws IOException {\n        if (tiles.length != REGION_SLOTS) {\n            throw new IllegalArgumentException("CausticaLOD dense region must contain " + REGION_SLOTS + " slots");\n        }\n        boolean any = false;\n        for (TileData tile : tiles) {\n            if (tile != null) {\n                any = true;\n                break;\n            }\n        }\n        if (!any) {\n            return;\n        }\n        Files.createDirectories(root);\n        Path target = regionPath(root, regionX, regionZ);\n        Path tmp = target.resolveSibling(target.getFileName() + ".tmp");\n        int[] offsets = new int[REGION_SLOTS];\n        int[] lengths = new int[REGION_SLOTS];\n\n        try (RandomAccessFile file = new RandomAccessFile(tmp.toFile(), "rw")) {\n            file.setLength(0L);\n            file.seek(HEADER_BYTES);\n            for (int index = 0; index < REGION_SLOTS; index++) {\n                TileData tile = tiles[index];\n                if (tile == null) {\n                    continue;\n                }\n                byte[] compressed = compress(tile);\n                long offset = file.getFilePointer();\n                if (offset > Integer.MAX_VALUE) {\n                    throw new IOException("CausticaLOD region exceeds 2 GiB: " + target);\n                }\n                offsets[index] = (int) offset;\n                lengths[index] = compressed.length;\n                file.write(compressed);\n            }\n\n            file.seek(0L);\n            file.writeInt(MAGIC);\n            file.writeInt(VERSION);\n            file.writeInt(regionX);\n            file.writeInt(regionZ);\n            for (int i = 0; i < REGION_SLOTS; i++) {\n                file.writeInt(offsets[i]);\n                file.writeInt(lengths[i]);\n            }\n            file.getFD().sync();\n        } catch (Throwable t) {\n            try {\n                Files.deleteIfExists(tmp);\n            } catch (IOException ignored) {\n            }\n            throw t;\n        }\n\n        try {\n            Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);\n        } catch (IOException atomicUnsupported) {\n            Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING);\n        }\n\n        synchronized (READERS) {\n            RegionReader stale = READERS.remove(target.toAbsolutePath().normalize());\n            if (stale != null) {\n                stale.close();\n            }\n        }\n    }\n\n'''
s = s[:start] + new + s[end:]
p.write_text(s)

# Primitive region keys + dense publication ----------------------------------
p = Path('src/main/java/dev/comfyfluffy/caustica/rt/terrain/RtCausticaLodImporter.java')
s = p.read_text()
s = s.replace('        private final Set<Long> regionKeys = new HashSet<>();\n',
              '        private final LongOpenHashSet regionKeys = new LongOpenHashSet();\n', 1)
old = '''  ArrayList<Long> keys = new ArrayList<>(regionKeys);\n  keys.sort(Comparator.comparingLong(Long::longValue));\n  int count = 0;\n  for (long regionKey : keys) {\n      int rx = (int) (regionKey >> 32);\n      int rz = (int) regionKey;\n      HashMap<Integer, RtCausticaLodRegionStore.TileData> tiles = new HashMap<>(1024);\n      Path path = spoolPath(rx, rz);\n      try (DataInputStream in = new DataInputStream(new BufferedInputStream(Files.newInputStream(path), 1 << 16))) {\n          while (true) {\n              final int slot;\n              try {\n                  slot = in.readInt();\n              } catch (EOFException done) {\n                  break;\n              }\n              if (slot < 0 || slot >= 1024) {\n                  throw new IOException("Invalid CausticaLOD spool slot " + slot + " in " + path);\n              }\n              RtCausticaLodRegionStore.TileData previous = tiles.put(slot, readTile(in));\n              if (previous != null) {\n                  throw new IOException("Duplicate CausticaLOD spool slot " + slot + " in " + path);\n              }\n          }\n      }\n      RtCausticaLodRegionStore.writeRegion(sessionRoot, rx, rz, tiles);\n      Files.deleteIfExists(path);\n      count++;\n      if ((count & 31) == 0 || count == keys.size()) {\n          CausticaMod.LOGGER.info("CausticaLOD WynnLOD pack publish: {}/{} regions", count, keys.size());\n      }\n  }\n  return count;\n'''
new = '''  long[] keys = regionKeys.toLongArray();\n  java.util.Arrays.sort(keys);\n  int count = 0;\n  for (long regionKey : keys) {\n      int rx = (int) (regionKey >> 32);\n      int rz = (int) regionKey;\n      RtCausticaLodRegionStore.TileData[] tiles = new RtCausticaLodRegionStore.TileData[1024];\n      Path path = spoolPath(rx, rz);\n      try (DataInputStream in = new DataInputStream(new BufferedInputStream(Files.newInputStream(path), 1 << 16))) {\n          while (true) {\n              final int slot;\n              try {\n                  slot = in.readInt();\n              } catch (EOFException done) {\n                  break;\n              }\n              if (slot < 0 || slot >= tiles.length) {\n                  throw new IOException("Invalid CausticaLOD spool slot " + slot + " in " + path);\n              }\n              if (tiles[slot] != null) {\n                  throw new IOException("Duplicate CausticaLOD spool slot " + slot + " in " + path);\n              }\n              tiles[slot] = readTile(in);\n          }\n      }\n      RtCausticaLodRegionStore.writeRegion(sessionRoot, rx, rz, tiles);\n      Files.deleteIfExists(path);\n      count++;\n      if ((count & 31) == 0 || count == keys.length) {\n          CausticaMod.LOGGER.info("CausticaLOD WynnLOD pack publish: {}/{} regions", count, keys.length);\n      }\n  }\n  return count;\n'''
assert old in s
s = s.replace(old, new, 1)
p.write_text(s)
